export const getCreateOrderUrl = () => {
  return `/api/orders`;
};

/**
 * THE customer charge path (atomic wallet deduction + inventory
 * claim). Mounted behind the idempotency middleware — send a fresh
 * Idempotency-Key per purchase (checkout generates one per unit) so a
 * network retry or double-click cannot double-charge. Round-94 (F10):
 * the key ALSO engages the durable in-transaction guard
 * (idempotency_keys) — a retry after a Redis flush / TTL expiry / TTL
 * boundary replays the original ORDER (200 + Idempotent-Replayed:
 * true) instead of re-charging, and a purchase that raced a same-key
 * winner surfaces the winner's order, never a second charge.
 * Round-94 (F1): a risk soft_block-tagged buyer is refused 423 until
 * they re-authenticate (friction, not lockout).
 * @summary Purchase a product
 */
export const createOrder = async (
  createOrderBody: CreateOrderBody,
  options?: Parameters<typeof customFetch>[1],
): Promise<Order> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<Order>(getCreateOrderUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(createOrderBody),
  });
};

