export const getAdminLoginUrl = () => {
  return `/api/admin/login`;
};

/**
 * Password login with an exponential-backoff lockout: repeated
 * failures lock the account and return 429 ACCOUNT_LOCKED until
 * the lock expires. Soft-disabled accounts answer 401 with the
 * same body as a wrong password (no account-state leak). When
 * TOTP is enabled the response is the requires_2fa variant
 * (temp_token + requires_2fa) and the session is issued by the
 * (undocumented) POST /admin/login/verify-2fa instead.
 * @summary Admin login
 */
export const adminLogin = async (
  adminLoginBody: AdminLoginBody,
  options?: Parameters<typeof customFetch>[1],
): Promise<AdminAuthResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<AdminAuthResponse>(getAdminLoginUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(adminLoginBody),
  });
};

export const getAdminLoginMutationKey = () => ["adminLogin"] as const;

export const getAdminLoginMutationOptions = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof adminLogin>>,
    TError,
    AdminLoginMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof adminLogin>>,
  TError,
  AdminLoginMutationVariables,
  TContext
> => {
  const mutationKey = getAdminLoginMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof adminLogin>>,
    AdminLoginMutationVariables
  > = (props) => {
    const { data } = props ?? {};

    return adminLogin(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type AdminLoginMutationResult = NonNullable<Awaited<ReturnType<typeof adminLogin>>>;
export type AdminLoginMutationBody = BodyType<AdminLoginBody>;
export type AdminLoginMutationError = ErrorType<ErrorResponse>;
export type AdminLoginMutationVariables = { data: BodyType<AdminLoginBody> };

/**
 * @summary Admin login
 */
export const useAdminLogin = <TError = ErrorType<ErrorResponse>, TContext = unknown>(
  options?: {
    mutation?: UseMutationOptions<
      Awaited<ReturnType<typeof adminLogin>>,
      TError,
      AdminLoginMutationVariables,
      TContext
    >;
    request?: SecondParameter<typeof customFetch>;
  },
  queryClient?: QueryClient,
): UseMutationResult<
  Awaited<ReturnType<typeof adminLogin>>,
  TError,
  AdminLoginMutationVariables,
  TContext
> => {
  return useMutation(getAdminLoginMutationOptions(options), queryClient);
};

